"c4.pergunta": "Did turnout change?",
"c4.curto": {"t": "Turnout", "rotulo": 30},
"c4.todos_da_regiao": "all {n} in the {regiao}",
"c4.ponto_sinal": "{n} percentage points",
"c4.resposta": "It rose: {comp} more voters turned out, and abstention fell from {a1} to {a2} ({da}). But abstention rose in {n} states: {ufs}. Where abstention fell the most, Lula's share did not clearly rise more.",
"c4.hipotese": "Lula's share of the two-candidate vote rose more (and Flávio's fell more) where abstention fell more.",
"c4.aba1": {"t": "Where abstention rose and fell (count)", "rotulo": 44},
"c4.aba2": {"t": "Where the net change went (estimate)", "rotulo": 40},
