"g.aviso_nome": "{nome} †",
"dica.aviso_modelo": {"t": "Caution", "rotulo": 12},
"dica.aviso_modelo_txt": "the model does not describe this place well: some source falls outside 0% to 100%",
"c4.fig2.leg_seta": {"t": "turnout fell: the bar splits the loss", "rotulo": 46},
