"av.dica.titulo": "{pct} counted, {hora}",
"av.dica.contagem2": {"t": "Runoff count", "rotulo": 26},
"av.dica.mesmo_pct": {"t": "1st round, same % counted", "rotulo": 28},
"av.dica.maior_erro": {"t": "Largest error from then on", "rotulo": 28},
