"csv.col.hipoteses.versao": "the main test or a robustness check",
"csv.col.hipoteses.dentro_dos_estados": "yes: compares municipalities in the same state (state fixed effect); no: all municipalities together",
"csv.col.hipoteses.peso": "weight of each municipality in the regression",
"csv.col.hipoteses.variavel": "the variable tested and the controls",
"csv.col.hipoteses.n": "how many municipalities and how many states are included",
"csv.col.hipoteses.coef": "coefficient (points of change in Lula's share per point of the variable; in the supplementary rows, which have no hypothesis, votes gained by the candidate as % of first-round registered voters per point of the variable) and standard error clustered by state",
"csv.col.hipoteses.ic95_inf": "95% confidence interval of the coefficient from the clustered error (t with the number of states minus 1 degrees of freedom)",
"csv.col.hipoteses.ic95_selvagem_inf": "95% confidence interval from the wild cluster bootstrap, by test inversion: the one the charts show (T32)",
"csv.col.hipoteses.p_cr1": "p-value from the clustered error and from the wild cluster bootstrap (empty where not calculated)",
"csv.col.hipoteses.r2": "R² and its type (comum or dentro dos estados: ordinary or within states)",
"csv.col.hipoteses.efeito_interquartil_pp": "predicted difference in the change in Lula's share between a municipality in the bottom quartile and one in the top quartile of the variable, in points",
"csv.col.hipoteses.previsto": "sign predicted before the calculations, the classification (confirmada, contrária or inconclusiva: supported, contradicted or inconclusive) and whether the association is small (less than {meio} point)",
"csv.col.apuracao_ao_vivo.urnas_apuradas_pct": "% of voting machines counted at the reading and the time of the reading at the TSE",
"csv.col.apuracao_ao_vivo.lula_2t_pct": "Lula's share of the two-candidate vote in the runoff count up to that reading, in %",
"csv.col.apuracao_ao_vivo.lula_1t_mesmas_urnas_pct": "Lula's first-round share in the same voting machines already counted in the runoff, in %",
"csv.col.apuracao_ao_vivo.projecao_final_pct": "projection of the final result shown live, in % (Lula's share)",
"csv.col.apuracao_ao_vivo.lula_1t_por_uf_pct": "Lula's first-round share in the same voting machines, taken by state only, in % (check of the live page)",
"csv.col.dados_sociais.cd_tse": "municipality code at the TSE (5 digits) and at IBGE (7 digits), state and name",
"csv.col.dados_sociais.pct_60mais": "% of the resident population aged 60 or over (2022 Census)",
"csv.col.dados_sociais.alfab_15mais": "literacy rate of people aged 15 or over, in %, as published by IBGE (2022 Census)",
"csv.col.dados_sociais.pct_renda_ate_meio_sm": "% of residents in permanent private households with per capita household income of up to half a minimum wage, including those with no income (2022 Census, sample)",
"csv.col.dados_sociais.pib_pc": "GDP per capita in 2023, in reais, as published by IBGE, and its natural logarithm, which is the one used in the tests",
"csv.col.dados_sociais.densidade": "inhabitants per km² (2022 Census), as published by IBGE, and its natural logarithm, used in the tests",
"csv.col.dados_sociais.pct_evangelicos": "% of evangelicals among people aged 10 or over (2022 Census, sample; note N19)",
"csv.col.dados_sociais.pct_pretos_pardos": "% of Black and pardo (mixed-race) people in the resident population (2022 Census)",
"csv.col.dados_sociais.pop": "the denominators: resident population, aged 15 or over and aged 10 or over, area in km² and 2023 GDP in thousands of reais; all empty for Boa Esperança do Norte (MT), note N20",
"csv.col.testes_sociais.variavel": "the municipality characteristic and the election measure: ds (change in Lula's share), gL and gF (votes gained by Lula and by Flávio, as % of first-round registered voters), cap (Lula's share of the combined gain) and da (change in abstention)",
"csv.col.testes_sociais.dentro_dos_estados": "yes: compares municipalities in the same state (the deciding version); no: all municipalities together",
"csv.col.testes_sociais.n": "how many municipalities and how many states are included",
"csv.col.testes_sociais.coef": "coefficient (points of the measure per 1 point of the characteristic; per 1 log unit for GDP per capita and density) and standard error clustered by state",
"csv.col.testes_sociais.ic95_inf": "95% confidence interval of the coefficient from the clustered error",
"csv.col.testes_sociais.ic95_selvagem_inf": "95% confidence interval from the wild cluster bootstrap, by test inversion",
"csv.col.testes_sociais.p_cr1": "p-value from the clustered error and from the wild cluster bootstrap",
"csv.col.testes_sociais.p_holm": "the two p-values corrected by the Holm method across the 35 tests of the same version",
"csv.col.testes_sociais.efeito_interquartil": "predicted difference in the measure between a municipality in the bottom quartile and one in the top quartile of the characteristic, in points",
"csv.col.testes_sociais.associacao": "yes when both corrected p-values are below {p05}; the direction (positiva or negativa: positive or negative) and whether it is small (less than {meio} point between quartiles)",
"csv.col.de_onde_vieram.nivel": "Brazil, region or state, and how many municipalities are included (with all their polling stations)",
"csv.col.de_onde_vieram.fonte": "the source of vote gains: votes for the other first-round candidates, change in turnout or drop in blank and null votes",
